<?php
declare(strict_types=1);

/** ISO market matrix for the product's 195 UN-member-state markets. */
function country_profiles(): array
{
    static $profiles = null;
    if ($profiles !== null) return $profiles;
    $codes = preg_split('/\s+/', 'AF AL DZ AD AO AG AR AM AU AT AZ BS BH BD BB BY BE BZ BJ BT BO BA BW BR BN BG BF BI CV KH CM CA CF TD CL CN CO KM CG CD CR CI HR CU CY CZ DK DJ DM DO EC EG SV GQ ER EE SZ ET FJ FI FR GA GM GE DE GH GR GD GT GN GW GY HT HN HU IS IN ID IR IQ IE IL IT JM JP JO KZ KE KI KP KR KW KG LA LV LB LS LR LY LI LT LU MG MW MY MV ML MT MH MR MU MX FM MD MC MN ME MA MZ MM NA NR NP NL NZ NI NE NG MK NO OM PK PW PA PG PY PE PH PL PT QA RO RU RW KN LC VC WS SM ST SA SN RS SC SL SG SK SI SB SO ZA SS ES LK SD SR SE CH SY TJ TZ TH TL TG TO TT TN TR TM TV UG UA AE GB US UY UZ VU VE VN YE ZM ZW PS VA');
    $profiles=[];
    foreach ($codes as $code) $profiles[$code]=['code'=>$code,'currency'=>'USD','timezone'=>'UTC','date_format'=>'Y-m-d','phone_prefix'=>'','locale'=>'en','fallback_locale'=>'en','rtl'=>0,'address_format'=>'street, city, region, postal_code, country'];
    foreach (['TR'=>['TRY','Europe/Istanbul','d.m.Y','+90','tr',0,'street, district, postal_code, city, country'],'GB'=>['GBP','Europe/London','d/m/Y','+44','en',0,'street, city, postal_code, country'],'US'=>['USD','America/New_York','m/d/Y','+1','en',0,'street, city, region, postal_code, country'],'DE'=>['EUR','Europe/Berlin','d.m.Y','+49','de',0,'street, postal_code, city, country'],'FR'=>['EUR','Europe/Paris','d/m/Y','+33','fr',0,'street, postal_code, city, country'],'ES'=>['EUR','Europe/Madrid','d/m/Y','+34','es',0,'street, postal_code, city, country'],'IT'=>['EUR','Europe/Rome','d/m/Y','+39','it',0,'street, postal_code, city, country'],'PT'=>['EUR','Europe/Lisbon','d/m/Y','+351','pt',0,'street, postal_code, city, country'],'NL'=>['EUR','Europe/Amsterdam','d-m-Y','+31','nl',0,'street, postal_code, city, country'],'RU'=>['RUB','Europe/Moscow','d.m.Y','+7','ru',0,'country, postal_code, region, city, street'],'JP'=>['JPY','Asia/Tokyo','Y/m/d','+81','ja',0,'postal_code, prefecture, city, street, country'],'CN'=>['CNY','Asia/Shanghai','Y-m-d','+86','zh',0,'country, province, city, district, street, postal_code'],'KR'=>['KRW','Asia/Seoul','Y. m. d.','+82','ko',0,'postal_code, province, city, street, country'],'AE'=>['AED','Asia/Dubai','d/m/Y','+971','ar',1,'country, emirate, city, street'],'AU'=>['AUD','Australia/Sydney','d/m/Y','+61','en',0,'street, suburb, state, postal_code, country'],'CA'=>['CAD','America/Toronto','Y-m-d','+1','en',0,'street, city, province, postal_code, country'],'BR'=>['BRL','America/Sao_Paulo','d/m/Y','+55','pt',0,'street, city, state, postal_code, country']] as $code=>$values) if(isset($profiles[$code])) { [$profiles[$code]['currency'],$profiles[$code]['timezone'],$profiles[$code]['date_format'],$profiles[$code]['phone_prefix'],$profiles[$code]['locale'],$profiles[$code]['rtl'],$profiles[$code]['address_format']]=$values; $profiles[$code]['fallback_locale']=$profiles[$code]['locale']==='tr'?'en':$profiles[$code]['locale']; }
    return $profiles;
}

function country_profile(string $code): array { $profiles=country_profiles(); $code=strtoupper($code); if(!isset($profiles[$code])) throw new InvalidArgumentException('Unsupported country profile.'); return $profiles[$code]; }
